import{_ as e,o as a,c as o,a6 as t}from"./chunks/framework.DNkVJs23.js";const m=JSON.parse('{"title":"Informativa sulla privacy","description":"Informativa sulla privacy — Sapphire Star Codex","frontmatter":{"description":"Informativa sulla privacy — Sapphire Star Codex","head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/it/privacy/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/it/privacy/"}],["meta",{"property":"og:title","content":"Informativa sulla privacy | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"Informativa sulla privacy — Sapphire Star Codex"}]]},"headers":[],"relativePath":"it/privacy/index.md","filePath":"it/privacy/index.md"}'),r={name:"it/privacy/index.md"};function n(l,i,s,c,p,d){return a(),o("div",null,[...i[0]||(i[0]=[t('<h1 id="informativa-sulla-privacy" tabindex="-1">Informativa sulla privacy <a class="header-anchor" href="#informativa-sulla-privacy" aria-label="Permalink to &quot;Informativa sulla privacy&quot;">​</a></h1><p>In vigore dal 31 ottobre 2026. Ultimo aggiornamento del testo originale: 10 novembre 2026. Traduzione: 14 novembre 2026.</p><p>Questa informativa riguarda le app iOS, Android e HarmonyOS di Sapphire Star Codex e questo sito. Sviluppatore: <strong>eurekaffeine (刘耀晨)</strong>. Contatto: <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a>. Le funzioni variano secondo la piattaforma; non serve un account.</p><h2 id="dati-locali" tabindex="-1">Dati locali <a class="header-anchor" href="#dati-locali" aria-label="Permalink to &quot;Dati locali&quot;">​</a></h2><p>L’app conserva sul dispositivo preferenze di gioco, lingua e aspetto, cronologia delle ricerche e stato della navigazione, preferiti, set salvati e relativi nomi, inventari di decorazioni, talismani e armature. Questi dati servono alle funzioni dell’app e non vengono caricati al server dello sviluppatore. Lo sviluppatore non gestisce account né sincronizzazione cloud.</p><h2 id="permessi-e-raccolta-automatica" tabindex="-1">Permessi e raccolta automatica <a class="header-anchor" href="#permessi-e-raccolta-automatica" aria-label="Permalink to &quot;Permessi e raccolta automatica&quot;">​</a></h2><p>L’app non include SDK pubblicitari, di tracciamento, statistiche d’uso o invio automatico di segnalazioni di arresto anomalo. Le funzioni attuali non richiedono contatti, posizione, fotocamera, microfono o foto e non raccolgono identificativi pubblicitari. Sistema operativo e store possono trattare dati di installazione o diagnostica secondo le proprie regole. La diagnostica resa disponibile allo sviluppatore serve solo a risolvere problemi.</p><h2 id="contatti-e-servizi-esterni" tabindex="-1">Contatti e servizi esterni <a class="header-anchor" href="#contatti-e-servizi-esterni" aria-label="Permalink to &quot;Contatti e servizi esterni&quot;">​</a></h2><p>Contattando volontariamente lo sviluppatore via email, vengono ricevuti indirizzo, messaggio e allegati per rispondere, risolvere problemi e gestire richieste sulla privacy, non per marketing. Invia solo dati necessari. Gmail gestisce la posta secondo l’<a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">informativa Google</a>.</p><p>GitHub Pages ospita questo sito e può ricevere indirizzo IP e dati tecnici del browser: vedi l’<a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement" target="_blank" rel="noreferrer">informativa GitHub</a>. Non sono aggiunti statistiche delle visite, cookie pubblicitari o pixel di tracciamento. La ricerca è eseguita nel browser, che può conservare preferenze. I servizi esterni hanno proprie informative e possono trattare dati fuori dal tuo paese.</p><h2 id="contributi-e-backup" tabindex="-1">Contributi e backup <a class="header-anchor" href="#contributi-e-backup" aria-label="Permalink to &quot;Contributi e backup&quot;">​</a></h2><p>Alipay o WeChat Pay gestisce i contributi secondo le proprie condizioni. Il sito mostra solo codici statici, senza SDK di pagamento né ricezione di credenziali. Lo sviluppatore può vedere dati forniti al destinatario dalla piattaforma, come importo, data, nome visualizzato e nota, per verificare i contributi e risolvere problemi. La conservazione segue le regole della piattaforma e gli obblighi applicabili. Secondo le impostazioni del sistema, i dati dell’app possono essere inclusi in backup del dispositivo o cloud; lo sviluppatore non può leggere o eliminare tali backup.</p><h2 id="condivisione-conservazione-e-cancellazione" tabindex="-1">Condivisione, conservazione e cancellazione <a class="header-anchor" href="#condivisione-conservazione-e-cancellazione" aria-label="Permalink to &quot;Condivisione, conservazione e cancellazione&quot;">​</a></h2><p>Lo sviluppatore non vende o affitta dati personali e non li condivide per pubblicità. La posta passa dal fornitore indicato. Informazioni effettivamente possedute possono essere fornite per obblighi di legge o su richiesta esplicita.</p><p>Cancella i dati locali con le funzioni dell’app o le impostazioni del sistema. Disinstallazioni che mantengono i dati non li cancellano; gestisci separatamente i backup, che possono ripristinarli. Le preferenze del sito restano fino alla cancellazione o pulizia automatica del browser. I messaggi sono conservati solo per gestione, seguito o obblighi legali. I fornitori gestiscono propri registri e backup. Contattaci per accedere ai dati inviati, correggerli o chiederne la cancellazione, salvo obblighi di conservazione. Lo sviluppatore non può accedere da remoto ai dati rimasti solo sul dispositivo.</p><h2 id="sicurezza-minori-e-aggiornamenti" tabindex="-1">Sicurezza, minori e aggiornamenti <a class="header-anchor" href="#sicurezza-minori-e-aggiornamenti" aria-label="Permalink to &quot;Sicurezza, minori e aggiornamenti&quot;">​</a></h2><p>I dati locali sono protetti dai meccanismi del sistema operativo. Il sito usa HTTPS. I messaggi sono consultati solo per assistenza e privacy, con le protezioni del fornitore di posta. L’app non richiede profili personali o date di nascita e non raccoglie intenzionalmente dati di bambini. Un genitore può richiedere la cancellazione di informazioni inviate da un minore.</p><p>Informativa e data cambiano insieme alle pratiche di trattamento; le modifiche importanti sono annunciate sul sito o negli aggiornamenti dell’app. Permessi e consensi necessari a nuove funzioni sono richiesti separatamente: questa informativa non li sostituisce.</p><p><strong>eurekaffeine (刘耀晨)</strong> — <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a></p>',19)])])}const v=e(r,[["render",n]]);export{m as __pageData,v as default};
